  var enabled=FrozenConfigurationEditor.Save(Fresh(engine),approved.ManifestHash,ordinary.Where(id=>id!="TwinA").ToArray(),FrozenConfigurationEditor.Components(approved).Concat(new[]{"TwinA"}).ToArray(),new string[0],CancellationToken.None,null);
  var rules=enabled.JavaRules.Where(r=>r.ModId=="TwinA"||r.ModId=="TwinB").ToArray();Check(rules.Length==2&&rules[0].Hash==rules[1].Hash&&rules.Single(r=>r.ModId=="TwinA").Allowed&&!rules.Single(r=>r.ModId=="TwinB").Allowed&&!rules.Single(r=>r.ModId=="TwinB").Approved,"identical copied JARs keep independent source decisions through native publication");
  var approvalFile=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(enabled.RuntimeHome,".zombie_buddy/mod_approvals.json")));var serialized=((System.Collections.IEnumerable)approvalFile["mods"]).Cast<Dictionary<string,object>>().ToArray();Check(serialized.Any(r=>Equals(r["jar_hash"],rules[0].Hash)&&Equals(r["decision"],true)),"native Buddy approvals retain enabled hash instead of silently clearing conflicting path decisions");
